"""Materialize generated bytes through the canonical tenant-scoped content store."""

from mockazure.content.repository import begin_upload, finalize_upload, put_chunk


async def store_rendered(session, tenant, rendered, max_size):
    upload = await begin_upload(
        session, tenant, rendered.length, rendered.sha256, rendered.media_type, max_size=max_size
    )
    for ordinal, chunk in enumerate(rendered.chunks()):
        await put_chunk(session, tenant, upload, ordinal, chunk)
    return await finalize_upload(session, tenant, upload)
